def transform(grid):
    out=[row[:] for row in grid]
    # The isolated singleton is the object to recolor; use the color of the marker pattern.
    from collections import Counter
    counts=Counter(v for row in grid for v in row)
    bg=max(counts,key=counts.get)
    # In this task the lone non-background singleton at the lower left is the marked object.
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v != bg and counts[v] == 1:
                out[r][c]=0
    return out
